<template>
  <section ref="root" class="lyf-page lcs-page" :aria-label="reviewing?'核对指定托运':'填写指定托运'">
    <AssistantFlowHeader :title="reviewing?'核对指定托运':'指定托运'" :back-label="reviewing?'返回填写托运信息':'返回选择承运商'" @back="back" @close="$emit('close')"/>
    <main ref="scroll" class="lcs-scroll">
      <section class="lcs-hero"><h2>{{ scheme.name }}</h2><p>{{ confirmed.origin }} → {{ confirmed.destination }}</p><small>方案参考费用 {{ referencePrice }}，不作为托运约定价格。</small></section>
      <section class="lcs-card lcs-target"><header><h3>指定承运商</h3><button type="button" class="lcs-link" @click="$emit('providers')">修改</button></header><AssistantCarrierCard v-if="provider" :provider="provider" compact/><p v-else class="lcs-error">请先选择一家承运商</p></section>
      <details v-if="!reviewing&&pastRecords.length" class="lcs-card lcs-history"><summary>本次路线的托运记录（{{ pastRecords.length }}）</summary><button v-for="record in pastRecords" :key="record.id" type="button" @click="$emit('open-record',record)"><span>{{ record.provider.name }}<small>{{ record.id }}</small></span><b>{{ record.status }}</b></button></details>
      <ConsignmentSummary v-if="reviewing" :form="form"/>
      <template v-else>
        <section class="lcs-card" :data-error="!!errors.businessType"><h3>托运类型</h3><label class="lcs-field"><span>业务类型 <em>*</em></span><select :value="form.businessType" aria-label="托运业务类型" @change="changeBusiness($event)"><option>集装箱</option><option>散杂货</option></select></label><label v-if="form.businessType==='集装箱'" class="lcs-field"><span>用箱方式 <em>*</em></span><select :value="form.containerSource" aria-label="用箱方式" @change="changeSource($event)"><option>自有集装箱</option><option>承运商提供</option></select></label><label v-else class="lcs-field"><span>允许货品混装</span><select v-model="form.allowMix" aria-label="允许货品混装"><option>允许</option><option>不允许</option></select></label></section>
        <section class="lcs-card lcs-quantity-unit"><h3>配载方式</h3><fieldset class="lcs-choices" aria-label="配载方式"><label v-for="mode in billingModes" :key="mode" :class="{selected:form.billingMode===mode}"><input v-model="form.billingMode" type="radio" name="consignment-unit" :value="mode"/>{{ mode.slice(1) }}</label></fieldset><p class="lcs-muted">按所选方式填写货量并计算运费。</p></section>
        <section v-if="ownContainer" class="lcs-card" :data-error="!!errors.boxes"><header><h3>柜种信息 <em>*</em></h3><button type="button" class="lcs-link" @click="form.boxes.push({id:uid(),boxType:'',size:'',qty:'',remark:''})">＋ 添加箱型</button></header><fieldset v-for="(box,index) in form.boxes" :key="box.id" class="lcs-goods-row"><legend>箱型 {{ index+1 }}<button type="button" :aria-label="`删除箱型${index+1}`" @click="form.boxes.splice(index,1)">删除</button></legend><label class="lcs-field"><span>箱型</span><select v-model="box.boxType" :aria-label="`箱型${index+1}`"><option value="">请选择</option><option v-for="type in boxTypes" :key="type">{{ type }}</option></select></label><label class="lcs-field"><span>尺寸</span><select v-model="box.size" :aria-label="`尺寸${index+1}`"><option value="">请选择</option><option v-for="size in boxSizes" :key="size">{{ size }}</option></select></label><label class="lcs-field"><span>数量</span><input v-model="box.qty" :aria-label="`箱量${index+1}`" type="number" min="1" max="100000000" step="1" placeholder="请输入"/></label><label class="lcs-field"><span>备注</span><input v-model="box.remark" :aria-label="`箱备注${index+1}`" maxlength="50" placeholder="请输入"/></label></fieldset><p v-if="errors.boxes" class="lcs-error" role="alert">{{ errors.boxes }}</p></section>
        <section v-if="ownContainer" class="lcs-card" :data-error="!!errors.goods"><h3>运输货品 <em>*</em></h3><ConsignmentGoodsFields v-model:items="form.goods" prefix="整票" :billing-mode="form.billingMode" show-code/><p v-if="errors.goods" class="lcs-error" role="alert">{{ errors.goods }}</p></section>
        <section class="lcs-card" :data-error="!!errors.nodes"><header><h3>运输信息 <em>*</em></h3><button type="button" class="lcs-link" @click="form.nodes.push(newNode('卸货',confirmed.destination))">＋ 添加节点</button></header><label v-if="ownContainer" class="lcs-field"><span>运输路线</span><select :value="form.routeMode" aria-label="运输路线" @change="changeRoute($event)"><option>自定义</option><option>提重还空</option><option>提空还空</option></select></label><p v-if="errors.nodes" class="lcs-error" role="alert">{{ errors.nodes }}</p><section v-for="(node,index) in form.nodes" :key="node.id" class="lcs-node" :data-error="!!errors['node-'+node.id]"><header><h4>节点 {{ index+1 }}</h4><div class="lcs-node-tools"><button type="button" :disabled="index===0" :aria-label="`上移节点${index+1}`" @click="moveNode(index,-1)">↑</button><button type="button" :disabled="index===form.nodes.length-1" :aria-label="`下移节点${index+1}`" @click="moveNode(index,1)">↓</button><button type="button" :aria-label="`删除节点${index+1}`" @click="removeNode(index)">删除</button></div></header><label class="lcs-field"><span>节点类型</span><select :value="node.type" :aria-label="`节点类型${index+1}`" @change="changeNodeType(node,$event)"><option v-for="type in ownContainer?nodeTypes:['装货','卸货']" :key="type">{{ type }}</option></select></label><p v-if="node.region" class="lcs-region">查询地点：{{ node.region }}<span v-if="node.queryDate"> · 查询出运日期：{{ node.queryDate }}</span></p><label class="lcs-field"><span>具体地址 <em>*</em></span><select v-model="node.location" :aria-label="`节点地址${index+1}`"><option value="">请选择常用地址</option><option v-if="node.location&&!consignmentCommonAddresses.some(address=>address.location===node.location)" :value="node.location">{{ node.location }}</option><option v-for="address in nodeAddresses(node)" :key="address.id" :value="address.location">{{ address.label }} · {{ address.location }}</option></select></label><label class="lcs-field"><span>预计时间</span><input v-model="node.time" :aria-label="`节点预计时间${index+1}`" type="datetime-local"/></label><details class="lcs-optional"><summary>联系人信息<span>{{ node.contact||node.phone?'已填写':'选填' }}</span></summary><label class="lcs-field"><span>联系人</span><input v-model="node.contact" :aria-label="`节点联系人${index+1}`" maxlength="50" placeholder="选填"/></label><label class="lcs-field"><span>联系电话</span><input v-model="node.phone" :aria-label="`节点联系电话${index+1}`" type="tel" maxlength="25" placeholder="选填"/></label></details><ConsignmentGoodsFields v-if="!ownContainer&&['装货','卸货'].includes(node.type)" v-model:items="node.goodsItems" :prefix="`节点${index+1}`" :billing-mode="form.billingMode" :sources="node.type==='卸货'?sourcesBefore(form,index):undefined"/><p v-if="errors['node-'+node.id]" class="lcs-error" role="alert">{{ errors['node-'+node.id] }}</p></section></section>
        <section class="lcs-card" :data-error="!!errors.freight"><h3>运费设置</h3><div class="lcs-field"><span>计费条件</span><output>{{ form.billingMode }}（{{ total.unit }}）</output></div><label class="lcs-field"><span>期望运输单价 <em>*</em></span><div class="lcs-number"><input v-model="form.expectedUnitPrice" aria-label="期望运输单价" type="number" min="0.01" max="100000000" step="0.01" inputmode="decimal" placeholder="请输入"/><small>元/{{ total.unit }}</small></div></label><label class="lcs-field"><span>支付方式</span><select v-model="form.paymentMethod" aria-label="托运支付方式"><option value="">请选择</option><option>到付</option><option>月结</option><option>现结</option></select></label><div class="lcs-estimate"><span>预估总运费<small>{{ total.quantity }}{{ total.unit }} × {{ form.expectedUnitPrice||'—' }}元/{{ total.unit }}</small></span><strong>¥{{ money(total.amount) }}</strong></div><p v-if="errors.freight" class="lcs-error" role="alert">{{ errors.freight }}</p></section>
        <section class="lcs-card" :data-error="!!errors.modes"><h3>运输要求</h3><fieldset class="lcs-choices"><legend>期望运输方式 <em>*</em></legend><label v-for="mode in shipmentModes" :key="mode" :class="{selected:form.transportModes.includes(mode)}"><input v-model="form.transportModes" type="checkbox" :value="mode"/>{{ mode }}</label></fieldset><p v-if="errors.modes" class="lcs-error" role="alert">{{ errors.modes }}</p><fieldset class="lcs-choices"><legend>单据凭证</legend><label v-for="voucher in ['装货凭证','卸货凭证']" :key="voucher" :class="{selected:form.vouchers.includes(voucher)}"><input v-model="form.vouchers" type="checkbox" :value="voucher"/>{{ voucher }}</label></fieldset><label class="lcs-note"><span>备注</span><textarea v-model="form.remark" aria-label="托运备注" maxlength="200" rows="3" placeholder="请输入备注"/><small>{{ form.remark.length }}/200</small></label></section>
      </template>
    </main>
    <footer class="lcs-footer"><p v-if="error" class="lcs-error" role="alert">{{ error }}</p><p v-if="saved" class="lcs-saved" role="status">{{ saved }}</p><label v-if="reviewing" class="lcs-consent"><input v-model="consent" type="checkbox"/>我已核对托运信息和指定承运商</label><div><button type="button" class="lyf-secondary" :disabled="submitting" @click="reviewing?edit():saveDraft()">{{ reviewing?'返回修改':'保存草稿' }}</button><button type="button" class="lyf-primary" :disabled="submitting||!provider||(reviewing&&!consent)" @click="reviewing?submit():review()">{{ submitting?'提交中…':reviewing?'提交托运':'下一步，核对托运' }}</button></div></footer>
    <div v-if="pendingChange" class="lcs-backdrop" @click.self="pendingChange=null"><section ref="dialog" role="dialog" aria-modal="true" aria-label="确认修改托运信息" tabindex="-1" @keydown.esc.stop="pendingChange=null" @keydown.tab="trapDialogFocus"><h3>确认修改</h3><p>{{ pendingChange.message }}</p><div><button type="button" @click="pendingChange=null">取消</button><button type="button" class="lyf-primary" @click="applyChange">确认修改</button></div></section></div>
  </section>
</template>
<script setup>
import { computed,nextTick,ref,watch } from 'vue'
import AssistantFlowHeader from './AssistantFlowHeader.vue'
import AssistantCarrierCard from './AssistantCarrierCard.vue'
import ConsignmentGoodsFields from './ConsignmentGoodsFields.vue'
import ConsignmentSummary from './ConsignmentSummary.vue'
import { billingModes,consignmentCommonAddresses,boxSizes,boxTypes,clone,freight,isOwnContainer,money,newGoods,newNode,nodeTypes,shipmentModes,sourcesBefore,syncUnload,uid,validateConsignment } from './assistant-consignment-model.js'
import { consignmentStore,saveConsignment } from './assistant-consignment-store.js'
import './assistant-consignment.css'
const props=defineProps({scheme:{type:Object,required:true},confirmed:{type:Object,required:true},provider:Object,referencePrice:String})
const emit=defineEmits(['providers','back','close','submitted','open-record'])
const form=defineModel('form',{type:Object,required:true})
const root=ref(null),scroll=ref(null),reviewing=ref(false),consent=ref(false),submitting=ref(false),errors=ref({}),error=ref(''),saved=ref(''),pendingChange=ref(null),dialog=ref(null),reviewKey=ref('')
const ownContainer=computed(()=>isOwnContainer(form.value)),total=computed(()=>freight(form.value))
const pastRecords=computed(()=>consignmentStore.records.filter(r=>r.status!=='草稿'&&r.form.contextKey===form.value.contextKey))
let returnFocus=null
watch(pendingChange,value=>{if(root.value)for(const child of root.value.children)if(!child.classList.contains('lcs-backdrop'))child.inert=!!value;if(!value)nextTick(()=>{if(returnFocus?.isConnected)returnFocus.focus()})})
const fingerprint=computed(()=>JSON.stringify([form.value,props.provider?.id,props.scheme.id]))
watch(form,()=>{syncUnload(form.value);if(reviewing.value){reviewing.value=false;consent.value=false}saved.value='';error.value='';errors.value={}},{deep:true})
watch(()=>props.provider?.id,()=>{reviewing.value=false;consent.value=false})
function nodeAddresses(node){const city=(node.region||'').replace(/市$/,'');return [...consignmentCommonAddresses].sort((a,b)=>Number(!!city&&b.location.startsWith(city))-Number(!!city&&a.location.startsWith(city)))}
function back(){if(reviewing.value)edit();else emit('back')}
function edit(){reviewing.value=false;consent.value=false;error.value='';nextTick(()=>{scroll.value.scrollTop=0})}
async function review(){syncUnload(form.value);errors.value=validateConsignment(form.value,props.provider);error.value=Object.values(errors.value)[0]||'';if(error.value){await nextTick();scroll.value?.querySelector('[data-error="true"]')?.scrollIntoView({block:'start'});return}reviewKey.value=fingerprint.value;reviewing.value=true;consent.value=false;nextTick(()=>{scroll.value.scrollTop=0})}
function saveDraft(){try{const record=saveConsignment(form.value,props.provider,props.scheme);form.value.id=record.id;nextTick(()=>{saved.value=consignmentStore.storageError?'草稿仅在本次会话保存':'草稿已保存在本机'})}catch(e){error.value=e.message}}
async function submit(){if(submitting.value)return;if(!consent.value||fingerprint.value!==reviewKey.value){error.value='托运信息已变化，请重新核对';return}const issue=validateConsignment(form.value,props.provider);if(Object.keys(issue).length){reviewing.value=false;errors.value=issue;error.value=Object.values(issue)[0];return}submitting.value=true;try{const record=saveConsignment(form.value,props.provider,props.scheme,'待承运商确认');emit('submitted',record)}catch(e){error.value=e.message}finally{submitting.value=false}}
function requestChange(message,action){returnFocus=document.activeElement;pendingChange.value={message,action};nextTick(()=>dialog.value?.focus())}
function trapDialogFocus(event){const buttons=dialog.value?.querySelectorAll('button');if(!buttons?.length)return;const first=buttons[0],last=buttons[buttons.length-1];if(event.shiftKey&&(document.activeElement===first||document.activeElement===dialog.value)){event.preventDefault();last.focus()}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===dialog.value)){event.preventDefault();first.focus()}}
function applyChange(){const action=pendingChange.value?.action;pendingChange.value=null;action?.()}
function changeBusiness(event){const value=event.target.value;event.target.value=form.value.businessType;if(value===form.value.businessType)return;requestChange('切换业务类型会重新初始化用箱、货品和节点明细，运费与运输要求保留。',()=>{form.value.businessType=value;resetCargoNodes()})}
function changeSource(event){const value=event.target.value;event.target.value=form.value.containerSource;if(value===form.value.containerSource)return;requestChange('切换用箱方式会重新初始化货品和节点明细，请重新核对承接范围。',()=>{form.value.containerSource=value;resetCargoNodes()})}
function resetCargoNodes(){form.value.routeMode='自定义';form.value.boxes=[{id:uid(),boxType:'',size:'',qty:'',remark:''}];form.value.goods=[newGoods()];form.value.nodes=[newNode('装货',props.confirmed.origin),newNode('卸货',props.confirmed.destination)]}
function changeRoute(event){const value=event.target.value;event.target.value=form.value.routeMode;if(value===form.value.routeMode)return;requestChange('切换运输路线会重新初始化节点地址、时间和联系人。',()=>{form.value.routeMode=value;const types=value==='自定义'?['装货','卸货']:value==='提重还空'?['提重','装货','卸货','还空']:['提空','装货','卸货','还空'];form.value.nodes=types.map(type=>newNode(type,['提空','提重','装货'].includes(type)?props.confirmed.origin:props.confirmed.destination))})}
function removeNode(index){requestChange('删除节点会同时移除该节点的货品明细，相关卸货引用需要重新选择。',()=>form.value.nodes.splice(index,1))}
function moveNode(index,offset){const target=index+offset;if(target<0||target>=form.value.nodes.length)return;[form.value.nodes[index],form.value.nodes[target]]=[form.value.nodes[target],form.value.nodes[index]]}
function changeNodeType(node,event){const value=event.target.value;event.target.value=node.type;if(value===node.type)return;requestChange('修改节点类型会清空该节点的货品明细及相关引用。',()=>{node.type=value;node.goodsItems=['装货','卸货'].includes(value)?[newGoods()]:[]})}
</script>
